<?php

namespace Database\Factories;

use App\Models\Category;
use Illuminate\Database\Eloquent\Factories\Factory;

/**
 * @extends Factory<Category>
 */
class CategoryFactory extends Factory
{
    protected $model = Category::class;

    /**
     * Define the model's default state.
     *
     * The slug is generated by the model's saving event, so it is not set here.
     *
     * @return array<string, mixed>
     */
    public function definition(): array
    {
        return [
            'name'        => fake()->unique()->words(fake()->numberBetween(1, 3), true),
            'description' => fake()->boolean(80) ? fake()->sentence(12) : null,
            'parent_id'   => null,
            'is_active'   => fake()->boolean(85),
            'views'       => fake()->numberBetween(0, 5000),
        ];
    }

    /**
     * Indicate that the category is active.
     */
    public function active(): static
    {
        return $this->state(fn (): array => ['is_active' => true]);
    }

    /**
     * Indicate that the category is inactive.
     */
    public function inactive(): static
    {
        return $this->state(fn (): array => ['is_active' => false]);
    }

    /**
     * Indicate that the category is a subcategory of the given parent.
     */
    public function childOf(Category $parent): static
    {
        return $this->state(fn (): array => ['parent_id' => $parent->getKey()]);
    }
}
